-- ExamGrind verified daily current-affairs desk: 30 October 2026.
-- Every item below is independently checked against the linked competent official release.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-10-30-trial-index-services-production-august$$, $$2026-10-30$$,
$$MoSPI releases trial Index of Services Production for August 2026$$,
$$The Ministry of Statistics and Programme Implementation released a trial Index of Services Production (ISP) for August 2026, covering 19 service sub-sectors with base year 2024–25. It is an experimental monthly series designed to track activity in services in greater detail.$$,
$$The release is valuable for economic-statistics questions: an index number measures change against a base period, while a trial series is still being tested for data quality and methodology before it should be treated as a settled official series.$$,
$$MoSPI reported year-on-year movements for sub-sectors including trade, transport, telecom, banking, insurance, real estate and IT services. It explicitly says the monthly series is experimental and that railway, banking and insurance inputs are provisional and subject to annual revision. ISP is not the same as GDP or the Index of Industrial Production: it is a service-sector activity indicator with its own coverage and base year.$$,
$$Release of Sub-Sectoral Trial Index of Services Production (ISP) for August 2026 (Base Year 2024–25)$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330036&lang=1&reg=3$$,
$$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-10-29$$,
$$["MoSPI released the August 2026 trial ISP with base year 2024–25.","The experimental series covers 19 service sub-sectors.","The release says railway, banking and insurance data are provisional and revised annually.","ISP is distinct from both GDP and the Index of Industrial Production."]$$::jsonb,
$$[{"question":"Why should the August 2026 ISP be described as a trial series?","answer":"MoSPI says the monthly publication is experimental so it can test data quality, resilience and stakeholder feedback before the series is finalised."}]$$::jsonb,
$${"title":"Reading a service-sector index","steps":["Choose a base year for comparison.","Collect activity data from covered service sub-sectors.","Compile and publish an index with stated revision policy.","Use trends as evidence alongside, not as a substitute for, GDP estimates."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-green-hydrogen-offtake-commitments$$, $$2026-10-30$$,
$$India's signed green-hydrogen offtake commitments cross 5.5 lakh MTPA$$,
$$The Ministry of New and Renewable Energy reported that Indian companies had signed green-hydrogen-equivalent offtake commitments of about 5.56 lakh metric tonnes per annum by October 2026. The release links the commitments to the National Green Hydrogen Mission and says more than 70% is earmarked for exports.$$,
$$This is a clean-energy and industrial-policy item. It tests the distinction between an offtake agreement—a buyer’s commitment to purchase an output—and actual commissioned production or delivery.$$,
$$The National Green Hydrogen Mission was approved with an initial outlay of Rs 19,744 crore up to 2029–30 and has a stated 2030 production objective of at least 5 million metric tonnes per annum. The release describes signed contracts and anticipated investment; those figures do not mean the contracted hydrogen has already been produced. It also identifies green ammonia and green methanol as hydrogen derivatives relevant to shipping, fertiliser and refining use cases.$$,
$$India Leads Globally with Green Hydrogen Offtake Commitments Exceeding 5.5 Lakh MTPA Till October 2026$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329940&lang=1&reg=3$$,
$$Ministry of New and Renewable Energy / Press Information Bureau$$, $$2026-10-29$$,
$$["The release reports signed commitments of about 5.56 lakh MTPA of green-hydrogen equivalent.","More than 70% of the stated commitments are earmarked for exports.","The National Green Hydrogen Mission has an initial outlay of Rs 19,744 crore up to 2029–30.","An offtake agreement is a purchase commitment, not proof that production or delivery has occurred."]$$::jsonb,
$$[{"question":"What is an offtake agreement in a green-hydrogen project?","answer":"It is an agreement or commitment for a buyer to purchase future output; it is not evidence that the plant is already producing or delivering that output."}]$$::jsonb,
$${"title":"From hydrogen project to offtake","steps":["A developer plans production capacity.","A buyer agrees to purchase specified future output.","Finance and construction are arranged against the project plan.","Production and delivery begin only after commissioning and operations."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-esic-amnesty-scheme-extension$$, $$2026-10-30$$,
$$ESIC extends its New Amnesty Scheme 2025 to 31 December 2026$$,
$$The Employees' State Insurance Corporation extended the New Amnesty Scheme 2025 for three months, from 1 October to 31 December 2026, on existing terms. The one-time dispute-resolution scheme is intended to reduce eligible litigation and encourage compliance under the Employees' State Insurance framework.$$,
$$This is relevant to labour welfare and social security. It helps distinguish ESIC, which administers employees’ state insurance, from EPFO, and a one-time settlement window from a permanent waiver of statutory contributions.$$,
$$According to the official release, court cases filed up to 31 March 2025 are eligible under the scheme’s terms. It allows settlement of ad-hoc assessments on payment of actual contributions and interest without damages in the specified case, and provides routes for withdrawal of certain cases subject to conditions. The extension does not erase all dues or alter the underlying legal obligations outside the scheme.$$,
$$ESIC Extends the New Amnesty Scheme 2025 till 31 December 2026: More Time for Employers and Insured Persons to Resolve Pending Cases$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329854&lang=1&reg=3$$,
$$Ministry of Labour and Employment / Press Information Bureau$$, $$2026-10-29$$,
$$["ESIC extended the New Amnesty Scheme 2025 until 31 December 2026.","The extension is for three months on existing terms and conditions.","The release describes it as a one-time dispute-resolution initiative.","Court cases filed up to 31 March 2025 are eligible under the stated scheme terms."]$$::jsonb,
$$[{"question":"Does the ESIC amnesty extension permanently waive all statutory contributions?","answer":"No. It is a time-bound, conditional dispute-resolution window; the release still requires payment according to the specified settlement terms."}]$$::jsonb,
$${"title":"How a time-bound settlement window works","steps":["An eligible dispute falls within the scheme cutoff.","The employer or insured person seeks settlement under the terms.","Specified contribution, interest or damages conditions are met.","The related case may be resolved or withdrawn with required approval."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-narmada-control-authority-payment-modalities$$, $$2026-10-30$$,
$$Narmada Control Authority review committee approves modalities for outstanding award-project dues$$,
$$The Review Committee for the Narmada Control Authority adopted the Attorney General of India’s opinion and the 7 July 2026 Memorandum of Agreement among Gujarat, Maharashtra, Madhya Pradesh and Rajasthan. It approved modalities for payment of outstanding dues related to Narmada Water Disputes Tribunal Award projects within FY 2026–27.$$,
$$The decision is important for federal water governance: interstate river disputes can involve tribunal awards, inter-state agreements and specialised implementation authorities, rather than a unilateral decision by one riparian State.$$,
$$The official record describes action by the Review Committee, not a new tribunal award. The Narmada Water Disputes Tribunal Award provides the underlying allocation and project framework, while the Narmada Control Authority and its review mechanism support implementation and coordination. Students should keep the Narmada Water Disputes Tribunal distinct from the Cauvery or Krishna tribunal arrangements.$$,
$$15th Meeting of Review Committee for Narmada Control Authority adopts AGI opinion and Memorandum of Agreement and approves modalities for payment of outstanding dues$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330127&lang=1&reg=3$$,
$$Ministry of Jal Shakti / Press Information Bureau$$, $$2026-10-29$$,
$$["The Review Committee acted on matters related to the Narmada Control Authority.","The 7 July 2026 MoA involved Gujarat, Maharashtra, Madhya Pradesh and Rajasthan.","It approved payment modalities for outstanding NWDT Award project dues within FY 2026–27.","The action concerns implementation of an existing award framework, not a fresh tribunal award."]$$::jsonb,
$$[{"question":"Which four States are named in the Narmada MoA discussed by the Review Committee?","answer":"Gujarat, Maharashtra, Madhya Pradesh and Rajasthan."}]$$::jsonb,
$${"title":"Interstate river-award implementation","steps":["A tribunal award establishes the relevant framework.","States negotiate implementation arrangements.","A specialised authority and review process coordinate compliance.","Financial and project obligations are settled through agreed modalities."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-ganga-flood-control-board-restructuring$$, $$2026-10-30$$,
$$Ganga Flood Control Board takes up GFCC restructuring and launches groundwater-recharge app$$,
$$At its 19th meeting, the Ganga Flood Control Board discussed the revised mandate and restructuring of the Ganga Flood Control Commission (GFCC), including a Flood Management Information System. The meeting also launched the Punah Bharan mobile application to identify locations suitable for artificial groundwater recharge.$$,
$$This connects disaster-risk reduction, basin governance and Centre–State coordination. It is particularly useful for distinguishing the Ganga Flood Control Board, a high-level coordination forum, from the technical Ganga Flood Control Commission.$$,
$$The Ganga Flood Control Board was constituted on 18 April 1972 to support coordinated planning on flood, erosion and drainage problems in the Ganga Basin. The release says the GFCC’s revised scope includes basin-level planning, appraisal of flood-management schemes, river-morphology and sedimentation studies, and information-system development. The Punah Bharan app was developed by BISAG-N with the National Water Mission; it is a site-identification tool, not a substitute for statutory project appraisal or local hydrogeological assessment.$$,
$$Union Minister of Jal Shakti Chairs 19th Meeting of Ganga Flood Control Board in New Delhi$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2329935&lang=1&reg=1$$,
$$Ministry of Jal Shakti / Press Information Bureau$$, $$2026-10-29$$,
$$["The Ganga Flood Control Board was constituted on 18 April 1972.","It addresses coordinated planning for flood, erosion and drainage issues in the Ganga Basin.","GFCC restructuring includes a proposed Flood Management Information System.","Punah Bharan helps identify locations for artificial groundwater recharge."]$$::jsonb,
$$[{"question":"Who serves as Member Secretary of the Ganga Flood Control Board according to the release?","answer":"The Chairman of the Ganga Flood Control Commission (GFCC)."}]$$::jsonb,
$${"title":"Basin flood-management architecture","steps":["Basin States and Central agencies identify shared flood risks.","The Board provides high-level coordination.","GFCC appraises technical planning, schemes and studies.","Data systems and local recharge tools support risk-informed action."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-delhi-declaration-local-climate-action$$, $$2026-10-30$$,
$$ARISE Cities Forum adopts Delhi Declaration on local action for global climate goals$$,
$$The ARISE Cities Forum 2026 adopted the Delhi Declaration on Local Action for Global Climate Goals. The declaration calls for stronger multilevel climate action and sets out ten shared commitments that organisers intend to carry to COP31 in Antalya, Türkiye.$$,
$$This is an international-environment and urban-governance item. It illustrates how city and local-government platforms seek a role in implementing and informing climate action, while remaining distinct from a negotiated UNFCCC decision binding on Parties.$$,
$$The forum was organised by ICLEI South Asia with the National Institute of Urban Affairs and support from the Ministry of Housing and Urban Affairs. The listed commitments include adaptation, circularity, just transitions, climate finance, data systems and youth/community leadership. A forum declaration records collective intent; it does not amend India’s Nationally Determined Contribution or create a new treaty obligation.$$,
$$From Bharat to Antalya: Delhi Declaration 2026 Calls for Stronger Multilevel Climate Action Ahead of COP31$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330002&lang=1&reg=1$$,
$$Ministry of Housing and Urban Affairs / Press Information Bureau$$, $$2026-10-29$$,
$$["The Delhi Declaration was adopted at the ARISE Cities Forum 2026.","The Forum was organised by ICLEI South Asia and NIUA with MoHUA support.","The declaration sets out ten shared commitments on local climate action.","It is intended to carry urban priorities to COP31 in Antalya, Türkiye."]$$::jsonb,
$$[{"question":"Is the Delhi Declaration itself a UNFCCC decision adopted by all Parties?","answer":"No. It is a forum declaration expressing shared commitments and urban priorities; it does not itself amend a UNFCCC treaty decision or India’s NDC."}]$$::jsonb,
$${"title":"From city priorities to climate dialogue","steps":["Cities identify local climate and development needs.","A multilevel forum frames shared commitments.","Urban priorities are presented in wider climate dialogue.","National and international legal decisions still follow their own formal processes."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-india-post-uti-kyc-partnership$$, $$2026-10-30$$,
$$India Post and UTI Mutual Fund extend doorstep KYC-verification collaboration$$,
$$India Post and UTI Mutual Fund extended their collaboration under a Pan-India KYC Verification Project. The arrangement uses the postal network’s last-mile reach to facilitate know-your-customer verification for mutual-fund investors, including in remote and underserved areas.$$,
$$The update gives a practical financial-inclusion angle: KYC is an identity and compliance process used by regulated financial services, while a mutual fund is an investment vehicle and not a government deposit scheme.$$,
$$The release describes an expansion of an existing partnership, building on KYC remediation work to resolve pending documentation and compliance gaps. India Post’s role is facilitation through its network; it does not replace the applicable regulatory responsibilities of the fund house or the investor. Students should not infer that KYC completion guarantees an investment return or overrides suitability requirements.$$,
$$India Post and UTI Mutual Fund Strengthen Partnership to Expand Pan-India KYC Verification Services$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330193&lang=1&reg=3$$,
$$Ministry of Communications, Department of Posts / Press Information Bureau$$, $$2026-10-29$$,
$$["The collaboration is between India Post and UTI Mutual Fund.","It concerns a Pan-India KYC Verification Project.","KYC means Know Your Customer.","The stated objective is to improve access and compliance through last-mile postal reach."]$$::jsonb,
$$[{"question":"What does KYC stand for in this India Post–UTI Mutual Fund initiative?","answer":"Know Your Customer, the identity-verification and compliance process used in financial services."}]$$::jsonb,
$${"title":"Last-mile KYC facilitation","steps":["An investor needs to complete identity and documentation requirements.","The postal network helps reach the investor locally.","Verification information is processed under applicable financial-service rules.","A compliant investor can access eligible mutual-fund services."]}$$::jsonb, $$published$$, now()
),
(
$$2026-10-30-tawang-international-tourism-mart$$, $$2026-10-30$$,
$$14th International Tourism Mart opens in Tawang for North East tourism partnerships$$,
$$The 14th International Tourism Mart opened at Tawang, Arunachal Pradesh, bringing together tourism stakeholders from the eight North Eastern States with domestic and international buyers. The Ministry of Tourism presented the event as a platform for sustainable tourism, market links and local livelihood opportunities.$$,
$$The event is useful for regional geography and tourism-policy revision. It ties the North Eastern Region to tourism circuits, connectivity, sustainable livelihoods and programmes such as Swadesh Darshan, PRASHAD and UDAN.$$,
$$The release reports 43 international buyers from 22 countries, 42 domestic buyers from 16 States and Union Territories, and 81 sellers. It says the Mart returned to Tawang after 13 years; the second edition had been held there in 2013. Reported tourism-project sanctions and visitor figures are programme and statistical context, not a claim that every proposed facility or partnership is complete.$$,
$$14th International Tourism Mart Inaugurated in Tawang, Arunachal Pradesh$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2330273&lang=1&reg=3$$,
$$Ministry of Tourism / Press Information Bureau$$, $$2026-10-29$$,
$$["The 14th International Tourism Mart is being held at Tawang, Arunachal Pradesh.","It focuses on the eight North Eastern States.","The release reports 43 international buyers from 22 countries.","The Mart returned to Tawang after 13 years; its second edition was held there in 2013."]$$::jsonb,
$$[{"question":"Which State hosts the 14th International Tourism Mart at Tawang?","answer":"Arunachal Pradesh."}]$$::jsonb,
$${"title":"Tourism-market linkage","steps":["States showcase destinations and tourism products.","Buyers and sellers meet through structured business sessions.","Infrastructure and connectivity improve visitor access.","Community-based and sustainable tourism can support local livelihoods."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-10-30-trial-index-services-production-august$$,
$$2026-10-30-green-hydrogen-offtake-commitments$$,
$$2026-10-30-esic-amnesty-scheme-extension$$,
$$2026-10-30-narmada-control-authority-payment-modalities$$,
$$2026-10-30-ganga-flood-control-board-restructuring$$,
$$2026-10-30-delhi-declaration-local-climate-action$$,
$$2026-10-30-india-post-uti-kyc-partnership$$,
$$2026-10-30-tawang-international-tourism-mart$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
